/* Generated by Payload, with one local change: the admin renders per request
 * (see `connection()` below). Keep that change if Payload regenerates this file. */
import config from '@payload-config'
import '@payloadcms/next/css'
import type { ServerFunctionClient } from 'payload'
import { handleServerFunctions, RootLayout } from '@payloadcms/next/layouts'
import { connection } from 'next/server'
import React from 'react'

import { importMap } from './admin/importMap.js'
import './custom.scss'

type Args = {
  children: React.ReactNode
}

/**
 * The admin depends on who is signed in and reads the clock while rendering,
 * so it can't be prerendered under Cache Components. `instant = false` lets
 * this segment block (no static shell); `connection()` makes it request-time.
 * The public website keeps its static rendering — this is the /admin layout only.
 */
export const instant = false

const serverFunction: ServerFunctionClient = async function (args) {
  'use server'
  return handleServerFunctions({
    ...args,
    config,
    importMap,
  })
}

const Layout = async ({ children }: Args) => {
  await connection()
  return (
    <RootLayout config={config} importMap={importMap} serverFunction={serverFunction}>
      {children}
    </RootLayout>
  )
}

export default Layout
